(()=>{'use strict';const buttons=[...document.querySelectorAll('.desktop-materials [data-manifest]')],status=document.getElementById('materialsStatus');const encoder=new TextEncoder();let table;function crc32(bytes){if(!table){table=Array.from({length:256},(_,n)=>{for(let k=0;k<8;k++)n=n&1?0xedb88320^(n>>>1):n>>>1;return n>>>0})}let n=0xffffffff;for(const b of bytes)n=table[(n^b)&255]^(n>>>8);return(n^0xffffffff)>>>0}function header(size){const bytes=new Uint8Array(size);return{bytes,v:new DataView(bytes.buffer)}}function zip(files){const pieces=[],central=[];let offset=0;for(const f of files){const name=encoder.encode(f.path),data=f.data,crc=crc32(data);const h=header(30);h.v.setUint32(0,0x04034b50,true);h.v.setUint16(4,20,true);h.v.setUint16(6,0x800,true);h.v.setUint32(14,crc,true);h.v.setUint32(18,data.length,true);h.v.setUint32(22,data.length,true);h.v.setUint16(26,name.length,true);pieces.push(h.bytes,name,data);const c=header(46);c.v.setUint32(0,0x02014b50,true);c.v.setUint16(4,20,true);c.v.setUint16(6,20,true);c.v.setUint16(8,0x800,true);c.v.setUint32(16,crc,true);c.v.setUint32(20,data.length,true);c.v.setUint32(24,data.length,true);c.v.setUint16(28,name.length,true);c.v.setUint32(42,offset,true);central.push(c.bytes,name);offset+=30+name.length+data.length}let centralSize=central.reduce((n,b)=>n+b.length,0);const e=header(22);e.v.setUint32(0,0x06054b50,true);e.v.setUint16(8,files.length,true);e.v.setUint16(10,files.length,true);e.v.setUint32(12,centralSize,true);e.v.setUint32(16,offset,true);return new Blob([...pieces,...central,e.bytes],{type:'application/zip'})}for(const btn of buttons)btn.addEventListener('click',async()=>{const previous=buttons.map(b=>b.disabled);buttons.forEach(b=>b.disabled=true);status.hidden=false;try{status.textContent='正在整理素材，请保持此页面打开…';const r=await fetch(btn.dataset.manifest||'ebook/materials-all.json',{cache:'no-store'});if(!r.ok)throw Error('素材清单暂时无法读取');const manifest=await r.json();if(!manifest.files?.length)throw Error('此素材包尚在制作中');const files=[];for(const [i,f]of manifest.files.entries()){status.textContent=`正在整理素材 ${i+1} / ${manifest.files.length}…`;const res=await fetch(f.url,{cache:'no-cache'});if(!res.ok)throw Error(`${f.path} 未能下载（${res.status}）`);if((res.headers?.get('content-type')||'').toLowerCase().includes('text/html'))throw Error('登录状态可能已失效，请刷新页面重新登录后重试');const bytes=new Uint8Array(await res.arrayBuffer());if(f.bytes!==undefined&&bytes.length!==f.bytes)throw Error(`${f.path} 文件大小校验失败，请刷新后重试`);if(f.sha256){const digest=await crypto.subtle.digest('SHA-256',bytes);const hash=Array.from(new Uint8Array(digest),b=>b.toString(16).padStart(2,'0')).join('');if(hash!==f.sha256)throw Error(`${f.path} 文件内容校验失败，请刷新后重试`)}files.push({path:f.path,data:bytes})}const blob=zip(files);const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=manifest.filename||'准备礼物-故事二制作素材.zip';a.click();setTimeout(()=>URL.revokeObjectURL(url),120000);status.textContent='素材包已整理好，浏览器已开始下载'}catch(e){status.textContent=`素材包暂时未能下载：${e.message}。请刷新后重试。`}finally{buttons.forEach((b,i)=>b.disabled=previous[i])}})})();
